import { test, expect } from '@playwright/test';

test.describe('Error Toast Notification on Action Failure', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display error toast when an action fails', async ({ page }) => {
    // Setup: intercept the API call to simulate failure
    await page.route('**/api/user/profile', (route) => {
      route.abort('failed');
    });

    // Get the action button using getByRole
    const actionButton = page.getByRole('button', { name: /update profile/i });
    await expect(actionButton).toBeVisible();

    // Click the action button
    await actionButton.click();

    // Wait for the error toast to appear
    const errorToast = page.getByText(/failed to update profile/i);
    await expect(errorToast).toBeVisible();

    // Verify the toast has an error icon
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();

    // Verify the toast has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify the toast has a dismiss action
    await closeButton.click();
    await expect(errorToast).not.toBeVisible();
  });

  test('should not display error toast when action succeeds', async ({ page }) => {
    // Setup: intercept the API call to simulate success
    await page.route('**/api/user/profile', (route) => {
      route.continue();
    });

    // Get the action button using getByRole
    const actionButton = page.getByRole('button', { name: /update profile/i });
    await expect(actionButton).toBeVisible();

    // Click the action button
    await actionButton.click();

    // Wait for the success toast to appear
    const successToast = page.getByText(/profile updated successfully/i);
    await expect(successToast).toBeVisible();

    // Verify the success toast has a success icon
    const successIcon = page.getByRole('img', { name: /success/i });
    await expect(successIcon).toBeVisible();

    // Verify the success toast has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify the success toast has a dismiss action
    await closeButton.click();
    await expect(successToast).not.toBeVisible();
  });
});
